{"code": "import pandas as pd, openpyxl
files = ['BaoCaoTonKho.xlsx','DanhSachChiTietNhapHang.xlsx','DanhSachHoaDon.xlsx','DanhSachHoaDonChiTiet_1.xlsx','DanhSachHoaDonChiTiet_2.xlsx','DanhSachKhachHang.xlsx','DanhSachNhapHang.xlsx','DanhSachSanPham.xlsx','SoQuy.xlsx']
for f in files:
    xl = pd.ExcelFile(f)
    print(f"{f}: sheets={xl.sheet_names}")
    for s in xl.sheet_names:
        df = pd.read_excel(f, sheet_name=s, usecols=list(range(12)))
        cols = [c for c in df.columns]
        exp = [c for c in cols if 'hạn' in c.lower() or 'Hạn' in c or 'expir' in c.lower() or 'Exp' in c or 'ngày' in c.lower() or 'Ngày' in c]
        print(f"   [{s}] cols={cols}")
        if exp: print(f"      EXPIRATION cols: {exp}")
"}

